CREATE TABLE IF NOT EXISTS catalog.module_definition (code varchar(100) PRIMARY KEY, title_key varchar(200) NOT NULL, icon_key varchar(100) NOT NULL, status varchar(16) NOT NULL, contract_version varchar(40) NOT NULL);
CREATE TABLE IF NOT EXISTS catalog.module_exposure (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), module_code varchar(100) NOT NULL REFERENCES catalog.module_definition(code) ON DELETE RESTRICT, workspace varchar(20) NOT NULL, channel varchar(32) NOT NULL, display_order integer NOT NULL, feature_flag boolean NOT NULL DEFAULT true, runtime_status varchar(16) NOT NULL, catalog_version varchar(40) NOT NULL);
